#include <iostream>
#include <set>
#include <array>

int main() {
    std::array<int, 10> rawData = {7, 22, 9, 1, 18, 30, 100, 22, 85, 13};
    std::multiset<int> ms(rawData.cbegin(), rawData.cend());

    std::cout << "Count of 22: " << ms.count(22) << "\n";

    auto lb = ms.lower_bound(22);
    auto ub = ms.upper_bound(22);
    if (lb != ms.end()) {
        std::cout << "Lower bound of 22: " << *lb << "\n";
    }
    if (ub != ms.end()) {
        std::cout << "Upper bound of 22: " << *ub << "\n";
    }

    // C++17 structured binding with equal_range
    auto [first, second] = ms.equal_range(22);
    std::cout << "equal_range [first, second): ";
    for (auto it = first; it != second; ++it) {
        std::cout << *it << " ";
    }
    std::cout << "\n";

    return 0;
}

#include <iostream>
#include <set>
#include <string>

int main() {
    std::set<double> numbers = {2.1, 4.2, 9.5, 2.1, 3.7};

    std::cout << "Initial set elements: ";
    for (double n : numbers) {
        std::cout << n << " ";
    }
    std::cout << "\n";

    // Attempt insertion of new value
    auto [it1, inserted1] = numbers.insert(13.8);
    std::cout << *it1 << (inserted1 ? " was" : " was not") << " inserted\n";

    // Attempt insertion of duplicate value
    auto [it2, inserted2] = numbers.insert(9.5);
    std::cout << *it2 << (inserted2 ? " was" : " was not") << " inserted\n";

    std::cout << "Final set elements: ";
    for (double n : numbers) {
        std::cout << n << " ";
    }
    std::cout << "\n";

    return 0;
}
